struct StrBuf { chars: Vec<Str> }

fn int_to_str(n: Int) -> StrBuf {
    let mut chars = Vec()
    let mut num = n
    if num == 0 {
        chars.push("0".clone())
    } else {
        while num > 0 {
            let digit = num % 10
            num = num / 10
            chars.push(to_float(digit).to_int().to_str())
        }
    }
    StrBuf(chars)
}

fn str_len(s: Str) -> Int {
    chars(s).len()
}

